        canvas {
            border: 1px solid black;
        }
    </style>
</head>
<body>
    <input id="angle" type="number" value="45" />°
    <button id="start">Start</button>
    <canvas id="pendulum" width="400" height="400"></canvas>

    <script>
        const canvas = document.getElementById('pendulum');
        const ctx = canvas.getContext('2d');
        const gravity = 0.1; // acceleration due to gravity
        const length = 100; // length of the pendulum
        let angle = 45; // initial angle
        let velocity = 0; // initial velocity
        let isRunning = false;
        let ticks = 0;
        let acc = 0;

        function init() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            ctx.fillStyle = 'black';
            ctx.fillRect(0, 0, canvas.width, canvas.height);
            update();
            draw();
        }

        function update() {
            if (isRunning) {
                acc = -gravity / length * Math.sin(Math.PI / 180 * angle);
                velocity += acc;
                angle += velocity;
                ticks++;
            }
        }

        function draw() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            ctx.fillStyle = 'black';
            ctx.fillRect(0, 0, canvas.width, canvas.height);
            ctx.beginPath();
            ctx.arc(canvas.width / 2, canvas.height / 2, length, 0, 2 * Math.PI);
            ctx.fillStyle = 'white';
            ctx.arc(canvas.width / 2 + length * Math.sin(Math.PI / 180 * angle), canvas.height / 2 - length * Math.cos(Math.PI / 180 * angle), 5, 0, 2 * Math.PI);
            ctx.fill();
            requestAnimationFrame(draw);
        }

        document.getElementById('start').addEventListener('click', function() {
            isRunning = true;
            init();
        });

        document.getElementById('angle').addEventListener('input', function() {
            angle = parseInt(this.value);
        });

        init();
    </script>
</body>
</html>
```

